'use client';

import * as React from 'react';
import { Surface } from '../../components/surface/surface';
import { Label } from '../../components/label/label';
import { Chip } from '../../components/chip/chip';
import { Led } from '../../components/status/status';
import './hover-engraving.css';

/* ─────────────────────────────────────────────────────────
 * HOVER ENGRAVING (the reference design's .meta): a composition
 *   Surface(tip, pill) › Label(engraved) <b>kind</b> · details + Chip(tag) × n + Label(engraved) Led status
 *
 *   pass      the pointer crosses the block: nothing
 *   dwell     the block stays hovered 420 ms: the engraving fades in on settle,
 *             sliding 3 in from the block (beside) or 2 down (below)
 *   leave     it goes at once, on settle, no delay
 *   selected  hidden, and hidden while writing (the host passes open={false})
 * Reduce Motion: settle resolves to a crossfade, so it fades in place.
 * ───────────────────────────────────────────────────────── */

export type EngravingStatus = 'live' | 'waiting' | 'failed' | 'off';

export interface HoverEngravingProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** The block's kind, emphasised first: "LOG", "TASK", "TITLE". */
  kind: string;
  /** Then time, edits, other life events: "07:40", "SLEEP 6 H", "ALSO TIRED". */
  details?: string[];
  /** Tags derived from a cluster title or region, as hollow pills: "poster". */
  tags?: string[];
  /** The recognizer's status, with its LED: { led: 'live', text: 'RECOGNIZER ✓' }. */
  status?: { led: EngravingStatus; text: string };
  /** beside the first line of a text block (default), or below a material block. */
  placement?: 'beside' | 'below';
  /** Controlled: true shows it (after the dwell), false hides it (selected, writing). Default: the host's hover. */
  open?: boolean;
  /** With open, skip the dwell (a keyboard focus, a docs still). */
  immediate?: boolean;
}

/** A block's identity on a dwell: what it is, when, and where it came from. */
export const HoverEngraving = React.forwardRef<HTMLSpanElement, HoverEngravingProps>(function HoverEngraving(
  { kind, details = [], tags = [], status, placement = 'beside', open, immediate, className, ...props },
  ref,
) {
  return (
    <Surface
      ref={ref}
      as="span"
      material="tip"
      radius="pill"
      role="note"
      data-placement={placement}
      data-open={open === undefined ? undefined : String(open)}
      data-immediate={immediate ? '' : undefined}
      className={className ? `mu-engraving ${className}` : 'mu-engraving'}
      {...props}
    >
      <Label variant="engraved">
        <b>{kind}</b>
        {details.map((d) => ` · ${d}`).join('')}
      </Label>
      {tags.length > 0 && (
        <span className="mu-engraving-tags">
          {tags.map((t) => <Chip key={t} variant="tag">#{t}</Chip>)}
        </span>
      )}
      {status && (
        <Label variant="engraved" className="mu-engraving-status">
          <Led kind={status.led} />
          {status.text}
        </Label>
      )}
    </Surface>
  );
});

@import "../../components/tokens.css";
@import "../../components/chip/chip.css";
@import "../../components/status/status.css";

/* Hover engraving: a composition. It places the pill, times its dwell and lays out its parts; every
   paint is Surface(tip), Label(engraved), Chip(tag) and Led. Layout and timing: --mu-engraving-*. */
.mu-engraving {
  position: absolute;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: var(--mu-engraving-gap);
  height: var(--mu-engraving-height);
  padding: var(--mu-zero) var(--mu-engraving-pad);
  white-space: nowrap;
  pointer-events: none;
  opacity: var(--mu-zero);
  /* Leaving is immediate: no delay on the way out. */
  transition:
    opacity var(--mu-engraving-fade-ms),
    transform var(--mu-engraving-move-ms) var(--mu-spring-settle);
}
/* Beside the first line of a text block, so a stacked list below stays readable. */
.mu-engraving[data-placement="beside"] {
  left: calc(100% + var(--mu-engraving-beside-gap));
  top: var(--mu-engraving-beside-top);
  transform: translateX(calc((var(--mu-zero) - var(--mu-engraving-slide)) * var(--mu-travel-settle)));
}
/* Under a material block (a link, an image, a swatch). */
.mu-engraving[data-placement="below"] {
  left: var(--mu-zero);
  top: calc(100% + var(--mu-engraving-below-gap));
  transform: translateY(calc((var(--mu-zero) - var(--mu-engraving-rise)) * var(--mu-travel-settle)));
}
/* A dwell, not a pass: the host must stay hovered for 420 ms. */
.mu-icon-trigger:hover > .mu-engraving:not([data-open="false"]),
.mu-engraving[data-open="true"] {
  opacity: 1;
  transform: none;
  transition-delay: var(--mu-engraving-dwell-ms);
}
.mu-engraving[data-open="true"][data-immediate] { transition-delay: var(--mu-zero); }
.mu-engraving-tags { display: flex; gap: var(--mu-engraving-tag-gap); }
.mu-engraving-status > .mu-led { display: inline-block; margin-right: var(--mu-engraving-led-gap); vertical-align: var(--mu-engraving-led-lift); }
